const secret = $env.AVERONAI_NOTIFY_SHARED_SECRET;
const provided = $input.first().json.headers['x-averonai-notify-secret'];
if (!provided || provided !== secret) {
  throw new Error('Invalid or missing x-averonai-notify-secret header');
}
return $input.all();

const b = $input.first().json.body;
const rows = [
  ['New leads this week', b.newThisWeek],
  ['Total leads', b.stats.total],
  ['Buyers', `${b.stats.buyers} (${b.stats.hotBuyers} hot)`],
  ['High score (80+)', b.stats.highScore],
  ['Uncontacted 2h+', b.stats.uncontactedOver2h],
  ['Median time to first touch', b.stats.medianTimeToFirstTouchMinutes ?? 'no data yet'],
];
const tableRows = rows.map(([label, value]) =>
  `<tr><td style=\"padding:6px 0;border-bottom:1px solid #e6e6e6;color:#6b7280;\">${label}</td>` +
  `<td style=\"padding:6px 0;border-bottom:1px solid #e6e6e6;text-align:right;font-weight:600;\">${value}</td></tr>`
).join('');
const html = `<div style=\"max-width:480px;margin:0 auto;font-family:system-ui,sans-serif;\">` +
  `<h2 style=\"font:600 18px/1.3 system-ui,sans-serif;margin:0 0 12px;\">${b.companyName} — weekly lead report</h2>` +
  `<table style=\"width:100%;border-collapse:collapse;font:400 14px/1.6 system-ui,sans-serif;\">${tableRows}</table></div>`;
return [{ json: { to: b.recipient, subject: `Weekly lead report — ${b.newThisWeek} new this week`, html } }];
